import { test, expect } from '@playwright/test';

test.describe('Password Requirements Tooltip', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup');
  });

  test('should display tooltip when hovering over password requirements', async ({ page }) => {
    // Verify password input field is visible
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Hover over password requirements link to trigger tooltip
    const requirementsLink = page.getByRole('link', { name: /password requirements/i });
    await requirementsLink.hover();

    // Verify tooltip appears
    const tooltip = page.getByText(/password must contain at least 8 characters/i);
    await expect(tooltip).toBeVisible();

    // Verify tooltip content is correct
    await expect(tooltip).toContainText('uppercase');
    await expect(tooltip).toContainText('lowercase');
    await expect(tooltip).toContainText('number');
    await expect(tooltip).toContainText('special character');

    // Verify tooltip disappears when hovering away
    await requirementsLink.hover({ force: true });
    await page.waitForTimeout(50);
    await requirementsLink.hover({ force: true });
    await expect(tooltip).not.toBeVisible();
  });

  test('should not display tooltip when password requirements link is not visible', async ({ page }) => {
    // Navigate to a page without password requirements
    await page.goto('/about');

    // Verify password requirements link does not exist
    const requirementsLink = page.getByRole('link', { name: /password requirements/i });
    await expect(requirementsLink).not.toBeVisible();

    // Verify tooltip does not appear
    const tooltip = page.getByText(/password must contain at least 8 characters/i);
    await expect(tooltip).not.toBeVisible();

    // Verify password input field is not present
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).not.toBeVisible();
  });
});
